save(P/'timing.json',dict(started_utc='2026-10-29T17:11:02Z',finished_utc=end,elapsed_wall_seconds=seconds,elapsed_wall_minutes=round(seconds/60,1),image_count=len(metas),actual_input_tokens=None,actual_output_tokens=None,actual_cost=None,note='Veggklokketid, inkludert kildearbeid, nedlasting, tegning og rettinger. Faktisk token-/faktureringsregnskap er ikke tilgjengelig.'))
